import React,{useState} from 'react';
import {useResource} from '../../shared/state.js';
import {Icon} from '../../shared/icons.tsx';
import type {DocumentDraft} from '../../shared/creation.tsx';

export function ChapterCreateExtras({call,novelId,value,change}:{call:any;novelId:string;value:DocumentDraft;change:any}){
 const [panel,setPanel]=useState(''),[query,setQuery]=useState(''),[name,setName]=useState('');
 const people=useResource(()=>call('graph.list',{novelId,type:'character_card'}),[call,novelId]);
 const characters=value.characters||[],events=value.events||[];
 const set=(key:string,next:any)=>change((old:DocumentDraft)=>({...old,[key]:next}));
 return <section className="chapter-create-extras" aria-label="本章快捷关联">
  <div className="chapter-quick-actions"><button type="button" aria-expanded={panel==='people'} onClick={()=>setPanel(panel==='people'?'':'people')}><Icon name="person"/>出场人物{characters.length>0&&<small>{characters.length}</small>}</button><button type="button" aria-expanded={panel==='events'} onClick={()=>setPanel(panel==='events'?'':'events')}><Icon name="route"/>本章事件{events.length>0&&<small>{events.length}</small>}</button><small>可选 · 创建章节时一并保存</small></div>
  {panel==='people'&&<div className="chapter-quick-panel"><label>查找已有角色<input aria-label="查找已有角色" value={query} onChange={e=>setQuery(e.target.value)}/></label><div className="chapter-person-options">{people.value?.filter((p:any)=>p.type==='character_card'&&!p.deleted&&p.name.includes(query)).map((p:any)=><button type="button" key={p.id} aria-pressed={characters.some(c=>c.nodeId===p.id)} onClick={()=>set('characters',characters.some(c=>c.nodeId===p.id)?characters.filter(c=>c.nodeId!==p.id):[...characters,{nodeId:p.id,name:p.name}])}>{p.name}</button>)}</div>{people.error&&<p role="alert">{people.error}</p>}<div className="row"><input aria-label="新人物姓名" placeholder="新人物姓名" value={name} onChange={e=>setName(e.target.value)}/><button type="button" disabled={!name.trim()} onClick={()=>{set('characters',[...characters,{name:name.trim()}]);setName('');}}>＋ 新建人物</button></div><p className="muted">由你指定本章出场；可以先留空正文，之后再补写。</p></div>}
  {characters.length>0&&<div className="chapter-person-chips">{characters.map((c,i)=><button type="button" key={c.nodeId||`new-${i}`} aria-label={`移除出场人物 ${c.name}`} onClick={()=>set('characters',characters.filter((_,j)=>j!==i))}>{c.name}{!c.nodeId&&<small>新建</small>}<span aria-hidden="true">×</span></button>)}</div>}
  {panel==='events'&&<div className="chapter-quick-panel"><div className="row"><strong className="grow">本章事件</strong><button type="button" onClick={()=>set('events',[...events,{title:'',storyTime:'',content:''}])}>＋ 添加事件</button></div>{events.map((event,i)=><div className="chapter-event-draft" key={i}><div className="row"><input aria-label={`事件 ${i+1} 名称`} placeholder="未命名事件（可稍后补充）" value={event.title} onChange={e=>set('events',events.map((v,j)=>j===i?{...v,title:e.target.value}:v))}/><button type="button" aria-label={`移除事件 ${i+1}`} onClick={()=>set('events',events.filter((_,j)=>j!==i))}>×</button></div><input aria-label={`事件 ${i+1} 故事时间`} placeholder="故事时间（可选）" value={event.storyTime} onChange={e=>set('events',events.map((v,j)=>j===i?{...v,storyTime:e.target.value}:v))}/><textarea aria-label={`事件 ${i+1} 说明`} placeholder="事件说明（可选）" value={event.content} onChange={e=>set('events',events.map((v,j)=>j===i?{...v,content:e.target.value}:v))}/></div>)}<p className="muted">事件作为计划占位关联本章，可在时间线继续编辑、移动和删除。</p></div>}
 </section>;
}
